package com.commercecore.payment;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/v1/staff/refunds")public class StaffRefundController{private final PaymentService service;public StaffRefundController(PaymentService s){service=s;}@PostMapping("/{id}/reconcile")public PaymentDtos.RefundResponse reconcile(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id){return service.reconcileRefund(UUID.fromString(jwt.getSubject()),id);}}
